import React, {useEffect, useState} from 'react' 
import { useDispatch, useSelector } from "react-redux";
import { useLocation, useNavigate } from "react-router-dom";

import { getUserData, setUserData } from '../LocalStorangUser/LocalstorangUser';
import { LogalstorangUSER } from '../../../Redux/Actions/Usuario/Action-user';
import Loading from '../../loading/Loading';
import NavMenu from '../../navMenu/NavMenu';

const ComprasUser =()=>{
    const [loading, setLoading] = useState(true);
    const location = useLocation();
    const dispatch = useDispatch();
    const navigate = useNavigate();
   
    const user = useSelector((state) => state.USER);

    useEffect(() => {
        const timer = setTimeout(() => {
            setLoading(false);
        }, 3000);
        return () => clearTimeout(timer);
    }, []);

    useEffect(() => {
        const storedUser = getUserData();
        if (!user || user.state === "false") {
            if (!storedUser || storedUser.state === "false") {
                navigate('/');
            } else {
                dispatch(LogalstorangUSER(storedUser));
            }
        } else {
            setUserData(user);
        }
    }, [navigate, user, dispatch]);
    return <>
     {loading && <Loading />}
     <NavMenu />
    
    
    
    
    </>
}
export default ComprasUser;
